CREATE TABLE "public"."agent_memory" (
  "memory_id"         uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_id"           uuid                     NOT NULL,
  "memory_type"       text                     NOT NULL,
  "content"           jsonb                    NOT NULL DEFAULT '{}'::jsonb,
  "relevance"         double precision         DEFAULT 1.0,
  "source_session_id" uuid,
  "created_at"        timestamp with time zone DEFAULT now(),
  "expires_at"        timestamp with time zone,
  CONSTRAINT "agent_memory_memory_type_check" CHECK ((memory_type = ANY (ARRAY['session'::text, 'long_term'::text, 'preference'::text, 'flashcard'::text]))),
  CONSTRAINT "agent_memory_pkey" PRIMARY KEY (memory_id)
);

ALTER TABLE "public"."agent_memory"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."agent_trace" (
  "trace_id"        uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_id"         text                     NOT NULL,
  "session_id"      text                     NOT NULL,
  "turn_index"      integer,
  "route"           text                     NOT NULL,
  "steps"           jsonb                    NOT NULL DEFAULT '[]'::jsonb,
  "tool_calls"      integer                  NOT NULL DEFAULT 0,
  "handoffs"        integer                  NOT NULL DEFAULT 0,
  "checker_verdict" text,
  "latency_ms"      integer,
  "model_used"      text,
  "created_at"      timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "agent_trace_pkey" PRIMARY KEY (trace_id)
);

CREATE TABLE "public"."chat_turns" (
  "turn_id"             uuid                        NOT NULL DEFAULT gen_random_uuid(),
  "session_id"          uuid,
  "role"                text,
  "content"             text                        NOT NULL,
  "turn_index"          integer                     NOT NULL,
  "is_summarized"       boolean                     DEFAULT false,
  "concepts_referenced" text[],
  "agent_used"          text,
  "created_at"          timestamp without time zone DEFAULT now(),
  "presentation"        jsonb,
  CONSTRAINT "chat_turns_agent_used_check"
    CHECK
    (((agent_used IS NULL) OR (agent_used = ANY (ARRAY['student'::text, 'learning_agent'::text, 'graded_fast_path'::text, 'answer_checker'::text, 'solver'::text, 'socratic'::text,
    'quiz'::text,
    'practice_generator'::text,
    'diagnostic'::text,
    'follow_up'::text, 'context_manager'::text, 'orchestrator'::text, 'tutor'::text, 'syllabus'::text, 'doubt_resolver'::text, 'practice_coach'::text, 'mentor_briefing'::text])))),
  CONSTRAINT "chat_turns_pkey" PRIMARY KEY (turn_id),
  CONSTRAINT "chat_turns_role_check" CHECK ((role = ANY (ARRAY['user'::text, 'assistant'::text])))
);

ALTER TABLE "public"."chat_turns"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."concepts" (
  "concept_id"   text NOT NULL,
