);

ALTER TABLE "public"."content"
  ENABLE ROW LEVEL SECURITY;

CREATE TABLE "public"."learner_memory" (
  "memory_id"     uuid                     NOT NULL DEFAULT gen_random_uuid(),
  "user_id"       text                     NOT NULL,
  "kind"          text                     NOT NULL,
  "subject_key"   text,
  "fact"          text                     NOT NULL,
  "evidence"      text,
  "confidence"    real                     NOT NULL DEFAULT 0.6,
  "source"        text                     NOT NULL DEFAULT 'tutor'::text,
  "session_id"    text,
  "hit_count"     integer                  NOT NULL DEFAULT 0,
  "superseded_by" uuid,
  "created_at"    timestamp with time zone NOT NULL DEFAULT now(),
  "updated_at"    timestamp with time zone NOT NULL DEFAULT now(),
  CONSTRAINT "learner_memory_confidence_check" CHECK (((confidence >= (0.0)::double precision) AND (confidence <= (1.0)::double precision))),
  CONSTRAINT "learner_memory_kind_check" CHECK ((kind = ANY (ARRAY['preference'::text, 'misconception'::text, 'strength'::text, 'context'::text, 'goal'::text]))),
  CONSTRAINT "learner_memory_pkey" PRIMARY KEY (memory_id)
);

