  "event_type" text                     NOT NULL,
  "created_at" timestamp with time zone DEFAULT now(),
  CONSTRAINT "mastery_events_event_type_check" CHECK ((event_type = ANY (ARRAY['mastered'::text, 'unmastered'::text, 'weak_flagged'::text, 'weak_cleared'::text]))),
  CONSTRAINT "mastery_events_pkey" PRIMARY KEY (event_id)
);

