  "updated_at"          timestamp without time zone DEFAULT now(),
  "is_cold_start"       boolean                     DEFAULT true,
  "consecutive_correct" integer                     DEFAULT 0,
  "content_seen"        text[]                      DEFAULT '{}'::text[],
