  "decay_applied"       boolean                     DEFAULT false,
  CONSTRAINT "user_concept_state_pkey" PRIMARY KEY (user_id, concept_id),
  CONSTRAINT "user_concept_state_proficiency_score_check" CHECK (((proficiency_score >= (0)::double precision) AND (proficiency_score <= (1)::double precision)))
);

