-- Phase 1 (Study Session Fix Plan): durable turn presentation
-- Apply in Supabase SQL editor (or psql) before deploying agent code that writes `presentation`.
--
-- Stores slides / flashcards / grading_ui / structured lesson blobs that previously
-- lived only in file-backed carry (.carry_sessions/, 2h TTL).

ALTER TABLE public.chat_turns
  ADD COLUMN IF NOT EXISTS presentation jsonb;

COMMENT ON COLUMN public.chat_turns.presentation IS
  'Assistant-turn UI blob: slides, flashcards, grading_ui, quiz_assessment, card, structured, etc. Null for user turns.';

-- Prefer unique (session_id, turn_index). Skip if duplicates already exist —
-- clean duplicates first, then uncomment:
-- CREATE UNIQUE INDEX IF NOT EXISTS chat_turns_session_turn_uidx
--   ON public.chat_turns (session_id, turn_index);


-- ===== 002_schema_upgrade.sql =====
-- =============================================================================
-- Aeropt Schema Upgrade — Steps 1-5
-- Run this in Supabase SQL Editor (Dashboard → SQL Editor → New Query)
-- All statements are idempotent (safe to re-run).
-- =============================================================================

-- ─── Step 1: Add columns to user_concept_state ──────────────────────────────

ALTER TABLE public.user_concept_state
  ADD COLUMN IF NOT EXISTS consecutive_correct integer DEFAULT 0,
  ADD COLUMN IF NOT EXISTS content_seen text[] DEFAULT '{}',
  ADD COLUMN IF NOT EXISTS last_attempted_at timestamp with time zone,
  ADD COLUMN IF NOT EXISTS decay_applied boolean DEFAULT false;

-- ─── Step 2: Create user_learning_profile table ─────────────────────────────

CREATE TABLE IF NOT EXISTS public.user_learning_profile (
  user_id              uuid PRIMARY KEY REFERENCES public.users(user_id) ON DELETE CASCADE,
  learning_velocity    double precision DEFAULT 0,
  preferred_content_type text DEFAULT 'balanced'
    CHECK (preferred_content_type IN ('theory_first', 'practice_first', 'balanced')),
  weak_chapters        text[] DEFAULT '{}',
  strong_chapters      text[] DEFAULT '{}',
  total_study_minutes  integer DEFAULT 0,
  avg_session_minutes  double precision DEFAULT 0,
  error_dominant_type  text,
  streak_days          integer DEFAULT 0,
  last_study_date      date,
  created_at           timestamp with time zone DEFAULT now(),
  updated_at           timestamp with time zone DEFAULT now()
);

COMMENT ON TABLE public.user_learning_profile IS 'Global learning stats per user — consumed by Planner agent';

-- ─── Step 3: Create mastery_events table ────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.mastery_events (
  event_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id     uuid NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
  concept_id  text NOT NULL,
  old_score   double precision,
  new_score   double precision,
  event_type  text NOT NULL CHECK (event_type IN ('mastered', 'unmastered', 'weak_flagged', 'weak_cleared')),
  created_at  timestamp with time zone DEFAULT now()
);

CREATE INDEX IF NOT EXISTS idx_mastery_events_user
  ON public.mastery_events (user_id, created_at DESC);

COMMENT ON TABLE public.mastery_events IS 'Score transition log — Django event consumer listens for roadmap unlocks';

-- ─── Step 4: Create agent_memory table ──────────────────────────────────────

CREATE TABLE IF NOT EXISTS public.agent_memory (
  memory_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      uuid NOT NULL REFERENCES public.users(user_id) ON DELETE CASCADE,
  memory_type  text NOT NULL CHECK (memory_type IN ('session', 'long_term', 'preference', 'flashcard')),
  content      jsonb NOT NULL DEFAULT '{}',
  relevance    double precision DEFAULT 1.0,
  source_session_id uuid,
  created_at   timestamp with time zone DEFAULT now(),
  expires_at   timestamp with time zone
);

CREATE INDEX IF NOT EXISTS idx_agent_memory_user_type
  ON public.agent_memory (user_id, memory_type, created_at DESC);

COMMENT ON TABLE public.agent_memory IS 'Structured agent memory — replaces text blob summaries';

-- ─── Step 5: Add structured_memory to sessions ─────────────────────────────

ALTER TABLE public.sessions
  ADD COLUMN IF NOT EXISTS structured_memory jsonb;

COMMENT ON COLUMN public.sessions.structured_memory IS 'Structured JSON session memory (replaces text session_summary)';

-- ─── Verify ─────────────────────────────────────────────────────────────────
-- Run these SELECTs to confirm everything was created:

SELECT column_name, data_type FROM information_schema.columns
WHERE table_name = 'user_concept_state' AND column_name IN ('consecutive_correct', 'content_seen', 'last_attempted_at', 'decay_applied');

SELECT table_name FROM information_schema.tables
WHERE table_schema = 'public' AND table_name IN ('user_learning_profile', 'mastery_events', 'agent_memory');


-- ===== 002_users_preferred_depth_check.sql =====
-- Allow onboarding preferred_depth values used by Django + agent.
-- Run in Supabase SQL editor if preferred_depth sync fails with users_preferred_depth_check.

ALTER TABLE users DROP CONSTRAINT IF EXISTS users_preferred_depth_check;

ALTER TABLE users
  ADD CONSTRAINT users_preferred_depth_check
  CHECK (preferred_depth IS NULL OR preferred_depth IN ('quick', 'standard', 'deep'));


-- ===== 003_retire_structured_memory.sql =====
-- Remove agent_memory table and structured_memory column from sessions since they are unused.
DROP TABLE IF EXISTS public.agent_memory;
ALTER TABLE public.sessions DROP COLUMN IF EXISTS structured_memory;


-- ===== 004_content_gap_events.sql =====
-- Migration 004: Create content_gap_events table to log when retrieval yields no high-confidence hits.
-- Added status and updated_at so it can be used and updated by agents in the future.
--
-- concept_id is text with no foreign key: concepts.concept_id is text, and with the
-- local retrieval backend concept ids come from the retrieval index, not public.concepts.
-- (The first version declared uuid REFERENCES concepts and never applied anywhere.)

CREATE TABLE IF NOT EXISTS public.content_gap_events (
    event_id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
    user_id uuid REFERENCES public.users(user_id),
    session_id uuid REFERENCES public.sessions(session_id),
    concept_id text,
    query_text text NOT NULL,
    top_score float,
    status text DEFAULT 'pending',
    created_at timestamptz NOT NULL DEFAULT now(),
    updated_at timestamptz NOT NULL DEFAULT now()
);

-- Trigger to update 'updated_at' automatically
CREATE OR REPLACE FUNCTION update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
    NEW.updated_at = now();
    RETURN NEW;
END;
$$ language 'plpgsql';

DROP TRIGGER IF EXISTS update_content_gap_events_updated_at ON public.content_gap_events;
CREATE TRIGGER update_content_gap_events_updated_at
BEFORE UPDATE ON public.content_gap_events
FOR EACH ROW
EXECUTE PROCEDURE update_updated_at_column();

GRANT SELECT, INSERT, UPDATE ON TABLE public.content_gap_events TO service_role;


-- ===== 005_user_attempts_root_cause.sql =====
-- Migration 005: Add root_cause_concept_id to user_attempts
-- text with no foreign key, matching concepts.concept_id (text); the first version
-- declared uuid REFERENCES concepts and never applied, so agents/diagnostic.py's
-- writes of this column failed.
ALTER TABLE public.user_attempts
    ADD COLUMN IF NOT EXISTS root_cause_concept_id text;


-- ===== 006_learner_memory.sql =====
-- 006_learner_memory.sql
-- Durable learner memory for the autonomous Learning Agent.
--
-- Replaces the retired free-text-only memory model (see 003_retire_structured_memory.sql).
-- The difference from that retired attempt: this is NOT a dump of session state.
-- Each row is ONE atomic, evidence-backed fact the agent chose to remember about
-- a learner, with provenance and a confidence it can decay. The agent decides what
-- goes in here; nothing is written automatically by the pipeline.

-- ─── learner_memory ──────────────────────────────────────────────────────────
CREATE TABLE IF NOT EXISTS public.learner_memory (
  memory_id     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id       text NOT NULL,
  kind          text NOT NULL,          -- preference | misconception | strength | context | goal
  subject_key   text,                   -- concept_id / chapter this is about, when scoped
  fact          text NOT NULL,          -- one sentence, learner-scoped, no PII beyond what they told us
  evidence      text,                   -- why the agent believes it (turn, attempt, observation)
  confidence    real NOT NULL DEFAULT 0.6,
  source        text NOT NULL DEFAULT 'tutor',   -- tutor | coach | diagnostic
  session_id    text,
  hit_count     integer NOT NULL DEFAULT 0,      -- times recalled into a prompt
  superseded_by uuid REFERENCES public.learner_memory(memory_id) ON DELETE SET NULL,
  created_at    timestamptz NOT NULL DEFAULT now(),
  updated_at    timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT learner_memory_kind_check
    CHECK (kind IN ('preference', 'misconception', 'strength', 'context', 'goal')),
  CONSTRAINT learner_memory_confidence_check
    CHECK (confidence >= 0.0 AND confidence <= 1.0)
);

-- Recall path: active memories for a user, strongest first.
CREATE INDEX IF NOT EXISTS learner_memory_user_active_idx
  ON public.learner_memory (user_id, confidence DESC)
  WHERE superseded_by IS NULL;

-- Scoped recall: "what do we know about this concept for this learner".
CREATE INDEX IF NOT EXISTS learner_memory_user_subject_idx
  ON public.learner_memory (user_id, subject_key)
  WHERE superseded_by IS NULL;

COMMENT ON TABLE public.learner_memory IS
  'Atomic agent-authored facts about a learner. One fact per row, with evidence and confidence.';

-- ─── review_schedule ─────────────────────────────────────────────────────────
-- Spaced review the agent proposes. The Background Learning Coach reads due rows.
CREATE TABLE IF NOT EXISTS public.review_schedule (
  review_id    uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      text NOT NULL,
  concept_id   text NOT NULL,
  due_at       timestamptz NOT NULL,
  reason       text,
  status       text NOT NULL DEFAULT 'pending',  -- pending | done | cancelled
  created_by   text NOT NULL DEFAULT 'tutor',
  session_id   text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  completed_at timestamptz,
  CONSTRAINT review_schedule_status_check
    CHECK (status IN ('pending', 'done', 'cancelled'))
);

-- One open review per (user, concept): re-scheduling updates rather than piles up.
CREATE UNIQUE INDEX IF NOT EXISTS review_schedule_open_unique_idx
  ON public.review_schedule (user_id, concept_id)
  WHERE status = 'pending';

CREATE INDEX IF NOT EXISTS review_schedule_due_idx
  ON public.review_schedule (user_id, due_at)
  WHERE status = 'pending';

COMMENT ON TABLE public.review_schedule IS
  'Agent-proposed spaced review. Read by the Background Learning Coach when due.';

-- ─── agent_trace ─────────────────────────────────────────────────────────────
-- One row per agent turn: what the agent decided and why. This is the
-- observability replacement for reading conditional edges off a flowchart.
CREATE TABLE IF NOT EXISTS public.agent_trace (
  trace_id     uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id      text NOT NULL,
  session_id   text NOT NULL,
  turn_index   integer,
  route        text NOT NULL,            -- fast_path | agent_loop
  steps        jsonb NOT NULL DEFAULT '[]'::jsonb,   -- ordered tool calls / handoffs
  tool_calls   integer NOT NULL DEFAULT 0,
  handoffs     integer NOT NULL DEFAULT 0,
  checker_verdict text,                  -- pass | revised | failed | skipped
  latency_ms   integer,
  model_used   text,
  created_at   timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS agent_trace_session_idx
  ON public.agent_trace (session_id, created_at DESC);

COMMENT ON TABLE public.agent_trace IS
  'Per-turn decision trace for the autonomous Learning Agent: tools called, handoffs, checker verdict.';

-- The tutor reaches these tables through the Supabase service role.
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.learner_memory TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.review_schedule TO service_role;
GRANT SELECT, INSERT ON TABLE public.agent_trace TO service_role;


-- ===== 007_chat_turns_agent_used.sql =====
-- 007_chat_turns_agent_used.sql
--
-- Widen chat_turns.agent_used to cover the autonomous Learning Agent.
--
-- The original check constraint enumerated the nine graph nodes. Those nodes are
-- gone: one Learning Agent now writes the reply (sometimes accepting a composer
-- expert's draft verbatim), and the deterministic graded fast path handles
-- button clicks. Writing the student's own message also needs a label that says
-- "the student said this" rather than borrowing whichever node happened to
-- record it — the old code labelled user turns "orchestrator", which made the
-- column useless for telling who actually produced a turn.
--
-- Until this is applied, db.insert_chat_turn maps new labels onto legacy ones
-- (see _AGENT_USED_COMPAT there) so the service runs against either schema.
-- Once it is applied, that map can be emptied.

ALTER TABLE public.chat_turns
  DROP CONSTRAINT IF EXISTS chat_turns_agent_used_check;

ALTER TABLE public.chat_turns
  ADD CONSTRAINT chat_turns_agent_used_check
  CHECK (
    agent_used IS NULL
    OR agent_used IN (
      -- current
      'student',            -- the learner's own message
      'learning_agent',     -- the autonomous tutor's reply
      'graded_fast_path',   -- deterministic Correct/Incorrect handling
      'answer_checker',     -- a reply the checker rewrote
      -- still in use: composers and deterministic helpers
      'solver',
      'socratic',
      'quiz',
      'practice_generator',
      'diagnostic',
      'follow_up',
      'context_manager',
      -- retired, kept so historical rows stay valid
      'orchestrator',
      'tutor',
      'syllabus',
      'doubt_resolver',
      'practice_coach',
      'mentor_briefing'
    )
  );

COMMENT ON COLUMN public.chat_turns.agent_used IS
  'Who produced this turn: the student, the Learning Agent, or a named deterministic step.';


-- ===== 009_learner_memory_embedding.sql =====
-- 009_learner_memory_embedding.sql
-- Add an embedding column to learner_memory to support semantic recall.
-- Using real[] instead of vector(N) because the dimension varies between
-- local testing (static model, 256d) and production (Gemini, 3072d).

ALTER TABLE public.learner_memory ADD COLUMN IF NOT EXISTS embedding real[];


-- ===== 010_study_room.sql =====
-- 010_study_room.sql
-- Study Room: session tracking, event log, and readiness scores.
--
-- Three tables that power the Study Room's sequential learning flow
-- (Learn → Examples → Practice → Evaluation). The teacher agent writes
-- session state; the evaluation agent reads events and writes readiness.

-- ─── study_sessions ──────────────────────────────────────────────────────────
-- One row per Study Room session. Tracks the concept being studied,
-- what phase the student is in, and the overall session outcome.
CREATE TABLE IF NOT EXISTS public.study_sessions (
  study_session_id  uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           text NOT NULL,
  concept_id        text NOT NULL,
  concept_name      text,
  chapter           text,
  agent_session_id  text,                   -- links to the agent chat session
  current_phase     text NOT NULL DEFAULT 'learn',
  phase_history     jsonb NOT NULL DEFAULT '[]'::jsonb,
  questions_served  integer NOT NULL DEFAULT 0,
  questions_correct integer NOT NULL DEFAULT 0,
  difficulty_level  integer NOT NULL DEFAULT 1,
  started_at        timestamptz NOT NULL DEFAULT now(),
  completed_at      timestamptz,
  outcome           text,
  CONSTRAINT study_sessions_phase_check
    CHECK (current_phase IN ('learn','examples','practice','evaluation','completed')),
  CONSTRAINT study_sessions_outcome_check
    CHECK (outcome IS NULL OR outcome IN ('mastered','needs_review','incomplete'))
);

CREATE INDEX IF NOT EXISTS study_sessions_user_idx
  ON public.study_sessions (user_id, started_at DESC);
CREATE INDEX IF NOT EXISTS study_sessions_concept_idx
  ON public.study_sessions (user_id, concept_id);

COMMENT ON TABLE public.study_sessions IS
  'One row per Study Room session. Tracks concept, phase, difficulty, and outcome.';

-- ─── study_session_events ────────────────────────────────────────────────────
-- Every meaningful thing that happened in a study session.
CREATE TABLE IF NOT EXISTS public.study_session_events (
  event_id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  study_session_id  uuid NOT NULL REFERENCES public.study_sessions(study_session_id),
  user_id           text NOT NULL,
  event_type        text NOT NULL,
  concept_id        text,
  content_id        text,
  payload           jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT study_events_type_check
    CHECK (event_type IN (
      'phase_start','phase_end','concept_taught','example_shown',
      'question_served','question_attempted','doubt_asked','doubt_resolved',
      'difficulty_adjusted','review_scheduled','session_completed'
    ))
);

CREATE INDEX IF NOT EXISTS study_events_session_idx
  ON public.study_session_events (study_session_id, created_at);
CREATE INDEX IF NOT EXISTS study_events_user_concept_idx
  ON public.study_session_events (user_id, concept_id, event_type);

COMMENT ON TABLE public.study_session_events IS
  'Granular event log for Study Room sessions. Every concept taught, question attempted, and doubt resolved.';

-- ─── learner_readiness_scores ────────────────────────────────────────────────
-- Predicted readiness per concept and overall. Updated after every
-- study session completion by the Evaluation Agent.
CREATE TABLE IF NOT EXISTS public.learner_readiness_scores (
  score_id          uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id           text NOT NULL,
  concept_id        text,
  score             real NOT NULL,
  confidence        real NOT NULL DEFAULT 0.5,
  factors           jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT readiness_score_range CHECK (score >= 0.0 AND score <= 100.0),
  CONSTRAINT readiness_confidence_range CHECK (confidence >= 0.0 AND confidence <= 1.0)
);

CREATE UNIQUE INDEX IF NOT EXISTS readiness_scores_unique_idx
  ON public.learner_readiness_scores (user_id, COALESCE(concept_id, '__overall__'));

COMMENT ON TABLE public.learner_readiness_scores IS
  'Per-concept and overall exam readiness. Updated by the Evaluation Agent after each study session.';

-- Grants
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.study_sessions TO service_role;
GRANT SELECT, INSERT ON TABLE public.study_session_events TO service_role;
GRANT SELECT, INSERT, UPDATE ON TABLE public.learner_readiness_scores TO service_role;


-- ===== 011_study_lesson_plan.sql =====
-- 011_study_lesson_plan.sql
-- Study Room pacing: a visible lesson outline and per-phase progress.
--
-- Phase changes used to be left entirely to the model, which kept asking one
-- more check question instead of moving on ("I already know this — move on" got
-- another question). The teacher now commits to an outline for each phase and
-- ticks parts off; the server counts student turns in the current phase so it can
-- force the move when the model dawdles, and the UI shows "Part 2 of 3".
--
--   lesson_plan  {"learn": ["Energy storage", "The equation", "Frequency"],
--                 "examples": ["Find ω for given L, C", "Equal energy sharing"]}
--   phase_step   parts of the current phase already completed
--   phase_turns  student messages since the current phase started
--   evaluation_summary  the results-card text, so a finished session reopened
--                       from history still shows it

ALTER TABLE public.study_sessions
  ADD COLUMN IF NOT EXISTS lesson_plan jsonb NOT NULL DEFAULT '{}'::jsonb,
  ADD COLUMN IF NOT EXISTS phase_step  integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS phase_turns integer NOT NULL DEFAULT 0,
  ADD COLUMN IF NOT EXISTS evaluation_summary text;

NOTIFY pgrst, 'reload schema';


-- ===== 012_learning_events.sql =====
-- 012_learning_events.sql
-- One append-only ledger of everything a student does, across every surface.
--
-- Before this, progress lived in pieces: user_concept_state kept only the
-- latest proficiency (no history, so no trend), user_attempts had no surface or
-- score change, chat questions left no trace of which concept was worked on, and
-- Django's analytics tables (concept_mastery, question_attempts, daily_activity,
-- streaks) were never fed. The /progress page read those empty tables.
--
-- Every graded attempt (whichever path graded it), every tutor turn and every
-- study-session milestone now writes one row here. services/progress_report.py
-- derives streaks, active time, trends, chapter mastery and the mistake notebook
-- from it.
--
--   kind        attempt | tutor_turn | study_started | study_completed | review_done
--   source      chat | study | practice | assess | onboarding | review
--   outcome     correct | wrong (attempts); mastered | needs_review | incomplete (sessions)
--   proficiency_before / proficiency_after   the concept score around an attempt

CREATE TABLE IF NOT EXISTS public.learning_events (
  event_id            uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  user_id             text NOT NULL,
  kind                text NOT NULL,
  source              text NOT NULL DEFAULT 'chat',
  concept_id          text,
  content_id          text,
  session_id          text,
  study_session_id    text,
  outcome             text,
  error_type          text,
  difficulty          integer,
  time_taken_sec      integer,
  proficiency_before  double precision,
  proficiency_after   double precision,
  payload             jsonb NOT NULL DEFAULT '{}'::jsonb,
  created_at          timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT learning_events_kind_check
    CHECK (kind IN ('attempt','tutor_turn','study_started','study_completed','review_done'))
);

CREATE INDEX IF NOT EXISTS learning_events_user_time_idx
  ON public.learning_events (user_id, created_at DESC);
CREATE INDEX IF NOT EXISTS learning_events_user_concept_idx
  ON public.learning_events (user_id, concept_id, created_at DESC);

GRANT SELECT, INSERT ON public.learning_events TO service_role;

COMMENT ON TABLE public.learning_events IS
  'Append-only learner activity ledger across chat, study room, practice and assessments.';

-- ─── Backfill from what already exists ──────────────────────────────────────
-- Idempotent: only runs for users with no ledger rows yet.

INSERT INTO public.learning_events
  (user_id, kind, source, concept_id, content_id, session_id, outcome, error_type,
   time_taken_sec, payload, created_at)
SELECT a.user_id::text, 'attempt', 'chat', a.concept_id, a.content_id, a.session_id::text,
       CASE WHEN a.is_correct THEN 'correct' ELSE 'wrong' END, a.error_type,
       a.time_taken_sec,
       jsonb_build_object('student_answer', a.student_answer, 'backfilled', true),
       a.created_at AT TIME ZONE 'UTC'
FROM public.user_attempts a
WHERE NOT EXISTS (SELECT 1 FROM public.learning_events e WHERE e.user_id = a.user_id::text);

INSERT INTO public.learning_events
  (user_id, kind, source, concept_id, session_id, study_session_id, payload, created_at)
SELECT s.user_id, 'study_started', 'study', s.concept_id, s.agent_session_id,
       s.study_session_id::text, jsonb_build_object('backfilled', true), s.started_at
FROM public.study_sessions s
WHERE NOT EXISTS (
  SELECT 1 FROM public.learning_events e
  WHERE e.user_id = s.user_id AND e.kind <> 'attempt' AND e.payload->>'backfilled' IS NULL
)
AND EXISTS (SELECT 1 FROM public.chat_turns t WHERE t.session_id::text = s.agent_session_id);

INSERT INTO public.learning_events
  (user_id, kind, source, concept_id, session_id, study_session_id, outcome, difficulty,
   payload, created_at)
SELECT s.user_id, 'study_completed', 'study', s.concept_id, s.agent_session_id,
       s.study_session_id::text, s.outcome, s.difficulty_level,
       jsonb_build_object('questions_served', s.questions_served,
                          'questions_correct', s.questions_correct, 'backfilled', true),
       s.completed_at
FROM public.study_sessions s
WHERE s.completed_at IS NOT NULL
  AND NOT EXISTS (
    SELECT 1 FROM public.learning_events e
    WHERE e.study_session_id = s.study_session_id::text AND e.kind = 'study_completed'
  );

-- Study-room attempts are recorded with the study session's agent session id.
UPDATE public.learning_events e
SET source = 'study', study_session_id = s.study_session_id::text
FROM public.study_sessions s
WHERE e.kind = 'attempt' AND e.source = 'chat' AND e.session_id = s.agent_session_id;

NOTIFY pgrst, 'reload schema';


-- ===== 013_study_plan_settings.sql =====
-- 013_study_plan_settings.sql
-- Plan settings that the onboarding profile does not hold.
--
-- Exam, target year and daily minutes live in Django's student profile (set at
-- onboarding, edited from the Plan page via PATCH users/student-profiles/me/),
-- and the browser passes them to GET /api/v1/plan. These three are the plan's
-- own, kept here so they follow the student across devices:
--   study_days      days a week the student studies (rest days are planned)
--   revision_weeks  weeks before the exam kept free for revision and mocks
--   exam_date       the exact exam date, once NTA publishes it (else estimated)

CREATE TABLE IF NOT EXISTS public.study_plan_settings (
  user_id         text PRIMARY KEY,
  study_days      integer NOT NULL DEFAULT 6 CHECK (study_days BETWEEN 1 AND 7),
  revision_weeks  integer NOT NULL DEFAULT 6 CHECK (revision_weeks BETWEEN 0 AND 26),
  exam_date       date,
  updated_at      timestamptz NOT NULL DEFAULT now()
);

GRANT SELECT, INSERT, UPDATE ON public.study_plan_settings TO service_role;
NOTIFY pgrst, 'reload schema';


-- ===== 014_study_session_mode.sql =====
-- 014_study_session_mode.sql
-- Practice-only study sessions.
--
-- A student who already knows a topic wants questions, not a lesson. A session
-- in mode 'practice' starts in the practice phase (no Learn / Examples), and
-- question_source 'pyq' restricts it to JEE past-year questions.

ALTER TABLE public.study_sessions
  ADD COLUMN IF NOT EXISTS mode text NOT NULL DEFAULT 'learn',
  ADD COLUMN IF NOT EXISTS question_source text NOT NULL DEFAULT 'any';

DO $$ BEGIN
  ALTER TABLE public.study_sessions ADD CONSTRAINT study_sessions_mode_check CHECK (mode IN ('learn', 'practice'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;
DO $$ BEGIN
  ALTER TABLE public.study_sessions ADD CONSTRAINT study_sessions_source_check CHECK (question_source IN ('any', 'pyq'));
EXCEPTION WHEN duplicate_object THEN NULL; END $$;

NOTIFY pgrst, 'reload schema';


-- ===== 015_session_kind_title.sql =====
-- 015_session_kind_title.sql
-- General tutor chat history.
--
-- `kind` separates the general chat page's conversations ('chat') from the
-- sessions Study Room, lesson and doubt rooms open (NULL), so the chat history
-- lists only the student's own chats. `title` is the name the student gave a
-- chat; when NULL the list shows the first question instead. `deleted_at` is a
-- soft delete: the service role has no DELETE grant on sessions, and practice
-- records (user_attempts) point at sessions, so a deleted chat is hidden, not removed.

ALTER TABLE public.sessions
  ADD COLUMN IF NOT EXISTS kind text,
  ADD COLUMN IF NOT EXISTS title text,
  ADD COLUMN IF NOT EXISTS deleted_at timestamptz;

CREATE INDEX IF NOT EXISTS sessions_user_kind_updated_idx
  ON public.sessions (user_id, kind, updated_at DESC);

NOTIFY pgrst, 'reload schema';


-- ===== 016_durable_agent_state.sql =====
-- 016_durable_agent_state.sql
-- Supabase copies of state the agent otherwise keeps on local disk, for hosts
-- whose disk is wiped on restart (Hugging Face Spaces). Written and read by
-- services/durable_state.py when AEROPT_DURABLE_STATE=supabase; unused otherwise.
--
-- served_items   mirrors the retrieval novelty ledger (retrieval/store.py `served`),
--                so "don't repeat that question" survives a restart.
-- carry_sessions mirrors carry_store.py (quiz cursor, pending grading); 2-hour TTL
--                is applied on read, rows are deleted when a session ends.
-- Storage bucket `diagrams` holds compiled TikZ SVGs, private (served by the agent).
--
-- RLS is on with no policies: only the service role (which bypasses RLS) reads these.

CREATE TABLE IF NOT EXISTS public.served_items (
  user_id      text NOT NULL,
  content_id   text NOT NULL,
  concept_id   text,
  content_type text,
  purpose      text,
  fingerprint  text,
  served_at    double precision,
  times        integer NOT NULL DEFAULT 1,
  PRIMARY KEY (user_id, content_id)
);
CREATE INDEX IF NOT EXISTS served_items_user_concept_idx ON public.served_items (user_id, concept_id);

CREATE TABLE IF NOT EXISTS public.carry_sessions (
  session_id text PRIMARY KEY,
  carry      jsonb NOT NULL DEFAULT '{}'::jsonb,
  updated_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS carry_sessions_updated_idx ON public.carry_sessions (updated_at);

ALTER TABLE public.served_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.carry_sessions ENABLE ROW LEVEL SECURITY;

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.served_items TO service_role;
GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.carry_sessions TO service_role;

INSERT INTO storage.buckets (id, name, public)
VALUES ('diagrams', 'diagrams', false)
ON CONFLICT (id) DO NOTHING;

NOTIFY pgrst, 'reload schema';
